parameters.content:
### Branch A - Create + Fund Escrow
INPUT: { trade_id, buyer_address, seller_address, amount_usdc? }
OUTPUT: { status: SUCCESS, trade_id, create_tx_hash, fund_tx_hash, escrow_status }
ERROR: { status: FAILED, stage: CREATE_ESCROW|FUND_ESCROW, error_code, error_message, retryable }
SIDE EFFECT: writes escrow_accounts (PENDING then FUNDED) + blockchain_records rows.
IDEMPOTENCY: calling again for the same trade_id returns the existing escrow (already_anchored).

parameters.jsCode:
var body = $json.body || $json;
var trade_id = String(body.trade_id || body.tradeId || '');
var buyer_address = String(body.buyer_address || body.buyerAddress || '');
var seller_address = String(body.seller_address || body.sellerAddress || '');
var amount_usdc = body.amount_usdc != null ? Number(body.amount_usdc) : (body.amountUsdc != null ? Number(body.amountUsdc) : null);
return [{ json: { trade_id: trade_id, buyer_address: buyer_address, seller_address: seller_address, amount_usdc: amount_usdc } }];

var validated = $('Code - Validate Branch A Input').item.json;
var create = $('HTTP - Create Escrow').item.json;
var fund = $('HTTP - Fund Escrow').item.json;

function isError(d) {
  return !!(d && (d.detail || d.error));
}

if (isError(create)) {
  var d1 = create.detail || {};
  return [{ json: {
    status: 'FAILED',
    trade_id: validated.trade_id,
    stage: 'CREATE_ESCROW',
    error_code: d1.code || 'UNKNOWN',
    error_message: d1.message || create.error || 'Escrow creation failed',
    retryable: true
  } }];
}

if (isError(fund)) {
  var d2 = fund.detail || {};
  return [{ json: {
    status: 'FAILED',
    trade_id: validated.trade_id,
    stage: 'FUND_ESCROW',
    error_code: d2.code || 'UNKNOWN',
    error_message: d2.message || fund.error || 'Escrow funding failed',
    retryable: true
  } }];
}

return [{ json: {
  status: 'SUCCESS',
  trade_id: validated.trade_id,
  create_tx_hash: create.transaction_hash,
  fund_tx_hash: fund.transaction_hash,
  escrow_status: fund.status
} }];

parameters.content:
### Branch B - Document Anchor
INPUT: { trade_id }
OUTPUT: { status: SUCCESS, trade_id, transaction_hash, block_number, already_anchored }
ERROR: { status: FAILED, stage: ANCHOR_DOCUMENT, error_code, error_message, retryable }
  (e.g. NO_INVOICE if no COMMERCIAL_INVOICE document was uploaded for this trade yet)
SIDE EFFECT: writes a blockchain_records TRADE_ANCHOR row (CONFIRMED with a real tx hash).
IDEMPOTENCY: a trade already anchored returns the existing tx hash (already_anchored=true).

parameters.jsCode:
var body = $json.body || $json;
var trade_id = String(body.trade_id || body.tradeId || '');
return [{ json: { trade_id: trade_id } }];

var validated = $('Code - Validate Branch B Input').item.json;
var anchor = $('HTTP - Anchor Document').item.json;

function isError(d) {
  return !!(d && (d.detail || d.error));
}

if (isError(anchor)) {
  var d1 = anchor.detail || {};
  return [{ json: {
    status: 'FAILED',
    trade_id: validated.trade_id,
    stage: 'ANCHOR_DOCUMENT',
    error_code: d1.code || 'UNKNOWN',
    error_message: d1.message || anchor.error || 'Document anchor failed',
    retryable: true
  } }];
}

return [{ json: {
  status: 'SUCCESS',
  trade_id: validated.trade_id,
  transaction_hash: anchor.transaction_hash,
  block_number: anchor.block_number,
  already_anchored: anchor.already_anchored
} }];

parameters.content:
### Branch C - Shipment Event -> Release
INPUT: { trade_id, condition_kind: DOCS|SHIPMENT|INSPECTION, value? (default true) }
OUTPUT (released): { status: RELEASED, trade_id, release_tx_hash, set_condition_tx_hash }
OUTPUT (locked):   { status: LOCKED, trade_id, reason: CONDITIONS_NOT_MET, missing_conditions, state_label }
ERROR: { status: FAILED, stage: SET_CONDITION|GET_ESCROW_STATUS|RELEASE, error_code, error_message, retryable }
SIDE EFFECT: sets one condition flag; release only fires when all 3 are true. The IF node
  only decides whether to ASK the contract to release - the contract independently
  re-checks every condition and will revert if asked wrongly. No business rules live in n8n.
IDEMPOTENCY: setting the same condition twice is a no-op write; release on an already
  RELEASED escrow is rejected by the contract with the real on-chain reason.

parameters.jsCode:
var body = $json.body || $json;
var trade_id = String(body.trade_id || body.tradeId || '');
var kind = String(body.condition_kind || body.conditionKind || body.kind || 'SHIPMENT').toUpperCase();
if (kind !== 'DOCS' && kind !== 'SHIPMENT' && kind !== 'INSPECTION') {
  kind = 'SHIPMENT';
}
var value = body.value != null ? Boolean(body.value) : true;
return [{ json: { trade_id: trade_id, kind: kind, value: value } }];

var validated = $('Code - Validate Branch C Input').item.json;
var setResult = $('HTTP - Set Condition').item.json;
var statusResult = $('HTTP - Get Escrow Status').item.json;

function isError(d) {
  return !!(d && (d.detail || d.error));
}

if (isError(setResult)) {
  var d1 = setResult.detail || {};
  return [{ json: {
    status: 'FAILED',
    canRelease: false,
    trade_id: validated.trade_id,
    stage: 'SET_CONDITION',
    error_code: d1.code || 'UNKNOWN',
    error_message: d1.message || setResult.error || 'Failed to set condition',
    retryable: true
  } }];
}

if (isError(statusResult)) {
  var d2 = statusResult.detail || {};
  return [{ json: {
    status: 'FAILED',
    canRelease: false,
    trade_id: validated.trade_id,
    stage: 'GET_ESCROW_STATUS',
    error_code: d2.code || 'UNKNOWN',
    error_message: d2.message || statusResult.error || 'Failed to read escrow status',
    retryable: true
  } }];
}

var chain = statusResult.chain || {};
var docsVerified = !!chain.docsVerified;
var shipmentDelivered = !!chain.shipmentDelivered;
var inspectionPassed = !!chain.inspectionPassed;
var stateLabel = chain.stateLabel || 'UNKNOWN';
var allMet = docsVerified && shipmentDelivered && inspectionPassed;

var missing = [];
if (!docsVerified) { missing.push('docs_verified'); }
if (!shipmentDelivered) { missing.push('shipment_delivered'); }
if (!inspectionPassed) { missing.push('inspection_passed'); }

return [{ json: {
  status: 'CHECKED',
  canRelease: allMet && stateLabel === 'FUNDED',
  trade_id: validated.trade_id,
  state_label: stateLabel,
  missing_conditions: missing,
  set_condition_tx_hash: setResult.transaction_hash || null
} }];

var checkResult = $('Code - Check Release Conditions').item.json;
var releaseResult = $('HTTP - Release Escrow').item.json;

function isError(d) {
  return !!(d && (d.detail || d.error));
}

if (isError(releaseResult)) {
  var d1 = releaseResult.detail || {};
  return [{ json: {
    status: 'FAILED',
    trade_id: checkResult.trade_id,
    stage: 'RELEASE',
    error_code: d1.code || 'UNKNOWN',
    error_message: d1.message || releaseResult.error || 'Release failed',
    retryable: true
  } }];
}

return [{ json: {
  status: 'RELEASED',
  trade_id: checkResult.trade_id,
  release_tx_hash: releaseResult.transaction_hash,
  set_condition_tx_hash: checkResult.set_condition_tx_hash
} }];

var checkResult = $('Code - Check Release Conditions').item.json;

if (checkResult.status === 'FAILED') {
  return [{ json: checkResult }];
}

return [{ json: {
  status: 'LOCKED',
  trade_id: checkResult.trade_id,
  reason: 'CONDITIONS_NOT_MET',
  missing_conditions: checkResult.missing_conditions,
  state_label: checkResult.state_label,
  set_condition_tx_hash: checkResult.set_condition_tx_hash
} }];

parameters.content:
### Branch D - Dispute
INPUT: { trade_id }
OUTPUT: { status: DISPUTED, trade_id, transaction_hash, block_number }
ERROR: { status: FAILED, stage: RAISE_DISPUTE, error_code, error_message, retryable }
SIDE EFFECT: sets escrow_accounts.status=DISPUTED, dispute_active=true. This branch never
  connects to any release node - the dispute lock is structural in the contract
  (release() requires state==FUNDED, which DISPUTED is not), not an n8n-side rule.
IDEMPOTENCY: raising a dispute on an already-disputed escrow is rejected by the contract.

parameters.jsCode:
var body = $json.body || $json;
var trade_id = String(body.trade_id || body.tradeId || '');
return [{ json: { trade_id: trade_id } }];

var validated = $('Code - Validate Branch D Input').item.json;
var dispute = $('HTTP - Raise Dispute').item.json;

function isError(d) {
  return !!(d && (d.detail || d.error));
}

if (isError(dispute)) {
  var d1 = dispute.detail || {};
  return [{ json: {
    status: 'FAILED',
    trade_id: validated.trade_id,
    stage: 'RAISE_DISPUTE',
    error_code: d1.code || 'UNKNOWN',
    error_message: d1.message || dispute.error || 'Dispute raise failed',
    retryable: true
  } }];
}

return [{ json: {
  status: 'DISPUTED',
  trade_id: validated.trade_id,
  transaction_hash: dispute.transaction_hash,
  block_number: dispute.block_number
} }];
